import {createCalendar} from '../domain/time/calendar.js';
import {upcomingItems} from '../domain/time/occurrence.js';
import {WORLD_TASKS,modularWorldConfig,selectedWorldVersions} from '../domain/world-dynamics/tasks.js';
import {mainNavigation,rootTitle} from './navigation.js';
import {WORLD_KINDS} from '../domain/world-dynamics/data.js';
import {worldFields} from '../domain/world-dynamics/output.js';
import {worldDateText} from '../domain/world-dynamics/prompts.js';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,attrs='',kind='tertiary')=>`<button type="button" class="ui-button ui-button--${kind}" data-world-action="${action}" ${attrs}>${label}</button>`;
const field=(label,path,value,type='text')=>`<label class="ui-field time-field"><span class="ui-field__label">${label}</span><input class="ui-input" data-world-field="${path}" type="${type}" ${type==='number'?'min="1"':''} value="${e(value)}"></label>`;
const area=(label,path,value,prompt=false)=>`<label class="ui-field time-field"><span class="ui-field__label">${label}</span><textarea class="ui-input time-textarea${prompt?' lt-prompt-editor':''}" data-world-field="${path}">${e(value)}</textarea></label>`;
const rawArea=(label,path,value)=>`<textarea rows="8" class="ui-input time-textarea lt-prompt-editor" data-world-field="${path}" aria-label="${e(label)}">${e(value)}</textarea>`;
const switchControl=(label,path,value)=>`<button type="button" class="ui-switch" role="switch" aria-label="${e(label)}" aria-checked="${!!value}" data-world-action="toggle" data-path="${path}"><span class="ui-switch__track"><span class="ui-switch__knob"></span></span></button>`;
const toggle=(label,path,value)=>`<div class="time-reminder-row"><span>${e(label)}</span>${switchControl(label,path,value)}</div>`;
const chevron='<svg class="ui-prompt-chevron" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="m4 6 4 4 4-4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
function disclosure(s,key,label,body,control=''){return `<details class="ui-prompt-item" data-world-open="${e(key)}" ${s.consoleOpen?.[key]?'open':''}><summary>${chevron}<span class="ui-prompt-label">${e(label)}</span>${control}</summary><div class="ui-prompt-body">${body}</div></details>`;}
function themesBody(s,c){return c.themes.map((t,i)=>disclosure(s,`theme-${i}`,t.name,rawArea(t.name,`themes.${i}.content`,t.content),switchControl('启用'+t.name,`themes.${i}.enabled`,t.enabled))).join('');}
function ideasBody(s,c){return c.ideas.map((t,i)=>disclosure(s,`idea-${i}`,t.name||'新灵感',field('名称',`ideas.${i}.name`,t.name)+rawArea(t.name||'灵感内容',`ideas.${i}.content`,t.content)+button('删除灵感','remove-idea',`data-index="${i}"`,'danger'),switchControl('启用'+(t.name||'新灵感'),`ideas.${i}.enabled`,t.enabled))).join('')+button('新增灵感','add-idea');}
function materialSwitch(c,key,label){return switchControl('使用'+label,`materialEnabled.${key}`,c.materialEnabled?.[key]!==false);}
function sourceRow(label,value,control=''){return `<div class="ui-prompt-row"><span class="ui-prompt-label">${e(label)}</span>${value?`<small class="lt-meta">${e(value)}</small>`:""}${control}</div>`;}
function historySources(s){
 const all=selectedWorldVersions(s.domain,{}),plots=all.filter(v=>v.kind==='plot').flatMap(v=>v.entries),world=all.filter(v=>v.kind!=='plot');
 const dates=[...new Set(world.map(v=>worldDateText(v.version.date)))],grouped=new Map();
 for(const item of world){const key=item.version.id??item.version;if(!grouped.has(key))grouped.set(key,{version:item.version,entries:[]});grouped.get(key).entries.push(...item.entries);}
 return {plots,world:[...grouped.values()],dates};
}
function festivalText(s){try{const time=s.time,definition=time.calendars.find(row=>row.id===time.activeCalendarId),calendar=createCalendar(definition);return upcomingItems(calendar,time.items.filter(row=>row.kind==='holiday'),time.currentDate).map(row=>`${row.title}｜${worldDateText(row.start)}｜${row.description??''}`).join('\n');}catch{return '';}}
function materialsBody(s){const c=s.draft,{plots,world,dates}=historySources(s),festivals=festivalText(s),references=refs=>[...new Set(refs.map(r=>r.book))].map(book=>`${book}（${refs.filter(r=>r.book===book).length} 条）`).join('\n'),readOnly=text=>`<p class="time-evidence-text">${e(text)}</p>`;
 return `<div class="ui-prompt-list" data-world-material-inputs>
 ${sourceRow('当前日期',s.time?.currentDate?.day!=null?worldDateText(s.time.currentDate):'尚未识别',materialSwitch(c,'currentDate','当前日期'))}
 ${disclosure(s,'source-world','世界资料',button('选择世界书条目','books','data-purpose="worldRefs"')+readOnly(references(c.worldRefs)),`<small class="lt-meta">${c.worldRefs.length} 条</small>`+materialSwitch(c,'worldInfo','世界资料'))}
 ${disclosure(s,'source-extra','世界补充资料',rawArea('世界补充资料','extra',c.extra),`<small class="lt-meta" data-world-summary="extra">${c.extra.trim()?'已填写':'未填写'}</small>`)}
 ${disclosure(s,'source-people','人物资料',button('选择世界书条目','books','data-purpose="characterRefs"')+readOnly(references(c.characterRefs)),`<small class="lt-meta">${c.characterRefs.length} 条</small>`+materialSwitch(c,'characterInfo','人物资料'))}
 ${disclosure(s,'source-names','补充人物姓名',rawArea('补充人物姓名','extraPeople',c.extraPeople),`<small class="lt-meta" data-world-summary="extraPeople">${c.extraPeople.trim()?'已填写':'未填写'}</small>`)}
 ${disclosure(s,'source-festival','近期节日',readOnly(festivals||'无'),`<small class="lt-meta">${festivals?festivals.split('\n').length+' 条':'无'}</small>`+materialSwitch(c,'festivalInfo','近期节日'))}
 ${disclosure(s,'source-plots','已有长期剧情库',readOnly(plots.map(row=>row.text).join('\n\n')||'无'),`<small class="lt-meta">${plots.length?plots.length+' 条':'无'}</small>`+materialSwitch(c,'plotHistory','已有长期剧情库'))}
 ${disclosure(s,'source-history','上一版世界动态',readOnly(world.map(v=>`故事日期：${worldDateText(v.version.date)}\n`+v.entries.map(row=>row.text).join('\n\n')).join('\n\n')||'无'),`<small class="lt-meta">${dates.join(' / ')||'无'}</small>`+materialSwitch(c,'worldHistory','上一版世界动态'))}
 ${disclosure(s,'source-story','本轮剧情资料',`<fieldset class="ui-stacked-choices" aria-label="首次读取正文" data-world-story-controls><label class="ui-choice ui-choice--control-only ui-hit-owner"><input type="radio" data-world-field="initialScope" name="world-initial-scope" value="all" ${c.initialScope==='all'?'checked':''}><span>首次读取全部正文</span></label><div class="ui-choice-option"><label class="ui-choice ui-choice--control-only ui-hit-owner"><input type="radio" data-world-field="initialScope" name="world-initial-scope" value="recent" ${c.initialScope==='recent'?'checked':''}><span>首次读取最近</span></label><span class="ui-inline-number" data-world-recent-count><input class="ui-input" type="number" min="1" aria-label="首次读取的最近楼数" data-world-field="initialCount" value="${c.initialCount}" ${c.initialScope==='recent'?'':'disabled'}><span>楼</span></span></div></fieldset>`,switchControl('本轮剧情资料','readStory',c.readStory))}
 ${disclosure(s,'source-notes','本次补充要求',rawArea('本次补充要求','notes',c.notes),materialSwitch(c,'userNotes','本次补充要求'))}</div>`;
}
function presetBody(s){const c=s.draft,migration=modularWorldConfig(c),tasks=c.taskModules?Object.entries(WORLD_TASKS).map(([kind,label])=>disclosure(s,`task-${kind}`,label,rawArea(label,`taskModules.${kind}.content`,c.taskModules[kind].content)+(kind==='region'?themesBody(s,c):kind==='plot'?ideasBody(s,c):''),switchControl('启用'+label,`taskModules.${kind}.enabled`,c.taskModules[kind].enabled))).join('')+disclosure(s,'commonTasks','完结影响',rawArea('完结影响','commonTasks',c.commonTasks)):disclosure(s,'tasks','任务原文',rawArea('原任务区','sections.tasks',c.sections.tasks)),design=rawArea('设计原文','sections.design',c.sections.design);return `<div class="ui-prompt-list">${migration.error?`<p class="lt-error">${e(migration.error)}</p>`:''}${disclosure(s,'identity','AI 身份',rawArea('AI身份原文','sections.identity',c.sections.identity))}${disclosure(s,'rules','基本规则',rawArea('基本规则原文','sections.rules',c.sections.rules))}${disclosure(s,'materials','资料原文',rawArea('资料原文','sections.materials',c.sections.materials))}${tasks}${disclosure(s,'design','设计思考',design)}</div>`;}

function consoleBody(s){const tab=s.consoleTab??'preset';return `<div class="time-stack"><nav class="time-state-tabs lt-view-switch ui-segment-group" role="group" aria-label="预设操作台导航">${[['preset','预设编辑'],['input','资料准备']].map(([key,label])=>`<button type="button" class="ui-button lt-type" data-world-action="console-tab" data-tab="${key}" aria-pressed="${tab===key}" ${tab===key?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="ui-action-grid time-entry-actions">${button('预览请求','prepare',s.busy?'disabled':'','secondary')}</div><div data-world-console-panel="${tab}">${tab==='input'?materialsBody(s):presetBody(s)}</div></div>`;}

function booksBody(s){return `<div class="time-stack">${s.bookList.length?s.bookList.map(b=>`<details class="time-category time-prompt-group time-world-disclosure" open><summary class="time-group-heading">${e(b.book)}</summary><div class="time-group-body time-stack">${b.entries.map(entry=>{const checked=s.draft[s.bookPurpose].some(ref=>ref.book===entry.book&&ref.uid===entry.uid);return `<details class="time-candidate-evidence time-world-disclosure" data-world-open="${e('book:'+JSON.stringify([entry.book,entry.uid]))}" ${s.consoleOpen?.['book:'+JSON.stringify([entry.book,entry.uid])]?'open':''}><summary><input type="checkbox" data-world-ref data-book="${e(entry.book)}" data-uid="${e(entry.uid)}" aria-label="选择${e(entry.name)}" ${checked?'checked':''}><span>${e(entry.name)}</span></summary><p class="time-evidence-text">${e(entry.content)}</p></details>`;}).join('')}</div></details>`).join(''):'<p class="lt-meta">当前没有可选择的关联世界书条目</p>'}</div>`;}

function entryCard(entry,book,currentDate,version){const f=worldFields(entry.text),name=f.名称??f.姓名??f.事件??WORLD_KINDS[entry.kind],timing=f.时间??(f.有效至?`有效至 ${f.有效至}`:'');const body=f.动向内容??f.动态内容??f.活动内容??f.舆论内容??f.动态??f.影响??'';const edit=book?button('编辑','entry',`data-id="${entry.id}" aria-label="编辑${e(name)}"`):`<button type="button" class="ui-icon-button ui-button--tertiary" data-world-action="entry" data-id="${entry.id}" aria-label="编辑${e(name)}"><img class="lt-icon" src="${new URL('./icons/edit.svg',import.meta.url)}" alt=""></button>`;
 if(entry.kind==='weather'){
  let today='',future=[];try{const cal=createCalendar(version.calendar);cal.validate(currentDate);for(const line of entry.text.split('\n')){const m=line.match(/^(\d{1,4})(?:年|[-/])(\d{1,2})(?:月|[-/])(\d{1,2})日?：\s*(.+)$/);if(!m)continue;const day=cal.validate({calendarId:version.calendar.id,year:+m[1],month:+m[2],day:+m[3]}),difference=cal.compare(day,currentDate);if(difference===0)today=line;else if(difference>0)future.push(line);}}catch{/* Another calendar or no complete current day has no matching forecast. */}
  return `<section class="time-prompt-group time-world-group"><h2 class="time-group-heading">天气环境</h2><div class="time-group-body"><article class="time-item time-record"><div class="time-item-main">${f.地点?`<p class="lt-meta">${e(f.地点)}</p>`:''}<p class="time-evidence-text" data-world-weather-today>${e(today||'暂无当天预报')}</p>${future.length?`<details class="time-category time-world-disclosure"><summary>后续天气</summary><p class="time-evidence-text">${e(future.join('\n'))}</p></details>`:''}</div><div class="time-record-actions">${edit}</div></article></div></section>`;
 }
 if(entry.kind==='plot'){const firstNode=(entry.text.split('关键节点：')[1]??'').split('\n').map(line=>line.trim()).find(Boolean)??f.关键节点??'';return `<section class="time-prompt-group time-world-group"><h2 class="time-group-heading">${e(name)}</h2><div class="time-group-body"><article class="time-item time-record"><div class="time-item-main">${timing?`<p class="lt-meta">${e(timing)}</p>`:''}<p class="time-evidence-text" data-world-plot-first>${e(firstNode)}</p><details class="time-category time-world-disclosure"><summary>完整剧情</summary><p class="time-evidence-text">${e(entry.text)}</p></details></div><div class="time-record-actions">${edit}</div></article></div></section>`;}
 return `<article class="time-item time-record"><div class="time-item-main"><h3>${e(name)}</h3>${timing?`<p class="lt-meta">${e(timing)}</p>`:''}${f.地点?`<p class="lt-meta">${e(f.地点)}</p>`:''}<p class="time-evidence-text">${e(body)}</p></div><div class="time-record-actions">${edit}</div></article>`;
}
function worldBody(s,book,currentDate){const version=s.domain?.current,selected=selectedWorldVersions(s.domain,s.config??s.draft),entries=selected.flatMap(v=>v.entries);return `<div class="time-stack"><p class="lt-meta">当前故事日期 · <time data-world-current-date>${currentDate?.day!=null?e(worldDateText(currentDate)):'尚未识别'}</time></p><div class="ui-action-grid time-entry-actions lt-work-actions">${button('预览请求','prepare',s.busy?'disabled':'','secondary')}${button(s.busy?'正在生成…':version?'更新世界':'生成初始世界','generate',s.busy?'disabled':'','primary')}</div>${version?.design?.trim()?`<details class="time-category time-world-disclosure" data-world-design><summary>本轮设计思路 <small class="lt-meta">${e(worldDateText(version.date))}</small></summary><p class="time-evidence-text">${e(version.design)}</p></details>`:''}${!entries.length?'<p class="lt-meta">暂无世界动态</p>':Object.entries(WORLD_KINDS).map(([kind,label])=>{const list=entries.filter(row=>row.kind===kind);return list.length?(['weather','plot'].includes(kind)?list.map(entry=>entryCard(entry,book,currentDate,selected.find(v=>v.kind===kind).version)).join(''):`<section class="time-prompt-group time-world-group"><h2 class="time-group-heading">${label}</h2><div class="time-group-body">${list.map(entry=>entryCard(entry,book)).join('')}</div></section>`):'';}).join('')}${s.busy?'<p class="lt-status" role="status">世界动态正在后台生成</p>':''}</div>`;}
export function worldDynamicsMarkup(s,{theme,availability,currentDate=s.time?.currentDate}={}){const root=s.route==='world',book=['paper-letter','purple-glow'].includes(theme),title=s.route==='console'?'预设操作台':s.route==='books'?'选择世界书条目':s.route==='entry'?'编辑世界动态':'发送内容预览';let body='';
 const editorMain=s.route==='entry';
 if(s.status==='loading')body='<p class="lt-status">正在读取世界动态…</p>';else if(s.status==='failed')body=button('重新读取','reload');else if(s.route==='world')body=worldBody(s,book,currentDate);else if(s.route==='console')body=consoleBody(s);else if(s.route==='books')body=booksBody(s);else if(s.route==='entry')body=area('动态正文','entryText',s.entryText);else if(s.route==='preview')body=`<div class="time-stack">${(s.request?.messages??[]).map(m=>`<section><h2 class="time-group-heading">${e(m.role)}</h2><p class="time-evidence-text">${e(m.content)}</p></section>`).join('')}</div>`;

 const footer=root?`<footer class="lt-footer">${mainNavigation({policy:availability(),current:'time',attribute:'data-time-action',actions:{time:'nav'},attributes:{time:'data-route="home"'}})}</footer>`:`<footer class="lt-footer ui-action-footer"><div class="wk-editor-footer">${s.route==='entry'?button('删除','delete-entry','','danger'):button('取消','back')}${button(s.route==='preview'?(s.busy?'正在生成…':'生成'):s.route==='books'?'添加':'保存',s.route==='preview'?'generate':s.route==='console'?'save-config':s.route==='entry'?'save-entry':'accept-books',s.route==='preview'&&s.busy?'disabled':'','primary')}</div></footer>`;
 return `<section class="lantai lt-time ui-workspace ui-graphic-controls" data-ui-theme="${theme}" data-time-route="world" data-world-route="${e(s.route)}" aria-label="世界动态"><header class="lt-header ui-header ${root?'lt-header--root':'ui-header--centered'}">${root?`<div class="lt-root-top">${rootTitle('time')}<button type="button" class="ui-icon-button ui-button--tertiary" data-time-action="close" aria-label="关闭兰台"><img class="lt-icon" src="${new URL('./icons/close.svg',import.meta.url)}" alt=""></button></div><nav class="ui-tablist" aria-label="时间主导航">${[['home','日历'],['world','世界动态'],['manage','管理']].map(([route,label])=>`<button type="button" class="ui-button lt-type" data-time-action="nav" data-route="${route}" ${route==='world'?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`:`<button type="button" class="ui-icon-button ui-button--tertiary" data-world-action="back" aria-label="返回"><img class="lt-icon" src="${new URL('./icons/back.svg',import.meta.url)}" alt=""></button><h1 class="ui-page-title">${e(title)}</h1><button type="button" class="ui-icon-button ui-button--tertiary" data-time-action="close" aria-label="关闭兰台"><img class="lt-icon" src="${new URL('./icons/close.svg',import.meta.url)}" alt=""></button>`}</header><main class="lt-main ui-main${editorMain?" ui-main--editor":""}" tabindex="-1">${s.error?`<p class="lt-error" role="alert">${e(s.error)}</p>`:''}${s.status==='preparing'?'<p class="lt-status">正在准备请求…</p>':''}${body}</main>${footer}</section>`;
}
export function bindWorldDynamicsEvents(container,controller){
 let consoleScroll=0,consoleBookPurpose=null,composing=false;const tabScroll={preset:0,input:0};
 const leaveBooks=save=>{const books=controller.inspect().route==='books';controller.back(save);if(books){const main=container.querySelector('.lt-main');if(main)main.scrollTop=consoleScroll;container.querySelector(`[data-world-action="books"][data-purpose="${consoleBookPurpose}"]`)?.focus({preventScroll:true});}};
 const patchChoices=()=>{const draft=controller.inspect().draft;if(!draft)return;const count=container.querySelector('[data-world-field="initialCount"]');if(count)count.disabled=draft.initialScope!=='recent';};
 const captureOpen=()=>{for(const n of container.querySelectorAll('details[data-world-open]'))controller.setOpen(n.dataset.worldOpen,n.open);};
 const focusIdea=(index,reveal=false)=>{const draft=controller.inspect().draft,next=draft?.ideas.length?container.querySelector(`[data-world-field="ideas.${Math.min(index,draft.ideas.length-1)}.name"]`):container.querySelector('[data-world-action="add-idea"]');next?.focus({preventScroll:true});if(reveal)next?.scrollIntoView?.({block:'nearest'});};
 const click=event=>{const node=event.target.closest('[data-world-action]');if(!node||node.disabled)return;captureOpen();const action=node.dataset.worldAction;if(action==='back')leaveBooks(false);else if(action==='accept-books')leaveBooks(true);else if(action==='console-tab'){const previous=controller.inspect().consoleTab??'preset';tabScroll[previous]=container.querySelector('.lt-main')?.scrollTop??0;controller.setConsoleTab(node.dataset.tab);const main=container.querySelector('.lt-main');if(main)main.scrollTop=tabScroll[node.dataset.tab];container.querySelector(`[data-world-action="console-tab"][data-tab="${node.dataset.tab}"]`)?.focus({preventScroll:true});}else if(action==='save-config')void controller.saveConfig();else if(action==='books'){consoleScroll=container.querySelector('.lt-main')?.scrollTop??0;consoleBookPurpose=node.dataset.purpose;void controller.chooseBooks(node.dataset.purpose);}else if(action==='toggle'){event.preventDefault();event.stopPropagation();controller.toggle(node.dataset.path,true);node.setAttribute('aria-checked',String(node.getAttribute('aria-checked')!=='true'));patchChoices();}else if(action==='add-idea'){controller.addIdea();focusIdea(controller.inspect().draft.ideas.length-1,true);}else if(action==='remove-idea'){const index=+node.dataset.index;controller.removeIdea(index);focusIdea(index);}else if(action==='prepare')void controller.prepare();else if(action==='generate')void controller.generate();else if(action==='entry')controller.openEntry(node.dataset.id);else if(action==='save-entry')void controller.saveEntry();else if(action==='delete-entry')void controller.saveEntry(true);else if(action==='dismiss-wait')controller.dismissWait();else if(action==='reload')void controller.load();};
 const change=event=>{const n=event.target;if(n.matches('[data-world-ref]')){controller.toggleRef(n.dataset.book,n.dataset.uid,n.checked);return;}const path=n.dataset.worldField;if(!path)return;if(path==='entryText')controller.editEntry(n.value);else controller.edit(path,n.type==='number'?Number(n.value):n.value);if(n.type==='radio'&&n.checked)patchChoices();if(['extra','extraPeople'].includes(path)){const summary=container.querySelector(`[data-world-summary="${path}"]`);if(summary)summary.textContent=n.value.trim()?'已填写':'未填写';}};
 const remember=event=>{const n=event.target;if(n.matches?.('details[data-world-open]')&&container.contains(n))controller.setOpen(n.dataset.worldOpen,n.open);};
 const keyboard=event=>{if(event.key!=='Escape'||event.isComposing||composing||event.keyCode===229||controller.inspect().route!=='books')return;event.preventDefault();event.stopPropagation();leaveBooks(false);};
 const startComposition=()=>{composing=true;},endComposition=()=>{composing=false;};
 container.addEventListener('click',click);container.addEventListener('input',change);container.addEventListener('change',change);container.addEventListener('toggle',remember,true);container.addEventListener('keydown',keyboard);container.addEventListener('compositionstart',startComposition);container.addEventListener('compositionend',endComposition);return()=>{container.removeEventListener('click',click);container.removeEventListener('input',change);container.removeEventListener('change',change);container.removeEventListener('toggle',remember,true);container.removeEventListener('keydown',keyboard);container.removeEventListener('compositionstart',startComposition);container.removeEventListener('compositionend',endComposition);};
}
